#!/usr/bin/env python3
"""Patch the Android project generated by `flutter create` for KOC ONE.
Works with both Groovy (build.gradle) and Kotlin DSL (build.gradle.kts) templates.
Usage: python3 tool/patch_android.py mobile
"""
import pathlib, re, shutil, sys

root = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else "mobile")
android = root / "android"
app = android / "app"

# ── Manifest: permissions + lock-screen alarm activity ──
manifest = app / "src/main/AndroidManifest.xml"
m = manifest.read_text()
perms = [
    "INTERNET", "ACCESS_NETWORK_STATE", "ACCESS_FINE_LOCATION", "ACCESS_COARSE_LOCATION",
    "ACCESS_BACKGROUND_LOCATION", "FOREGROUND_SERVICE", "FOREGROUND_SERVICE_LOCATION",
    "POST_NOTIFICATIONS", "USE_FULL_SCREEN_INTENT", "VIBRATE", "WAKE_LOCK", "RECEIVE_BOOT_COMPLETED",
    "ACCESS_NOTIFICATION_POLICY", "RECORD_AUDIO", "MODIFY_AUDIO_SETTINGS", "CAMERA",
    "BLUETOOTH", "BLUETOOTH_CONNECT",
]
block = "\n".join(f'    <uses-permission android:name="android.permission.{p}"/>' for p in perms if f"permission.{p}\"" not in m)
m = m.replace("<application", block + "\n    <application", 1)
m = re.sub(r'android:label="[^"]*"', 'android:label="KOC ONE"', m, count=1)
if "showWhenLocked" not in m:
    m = m.replace('android:name=".MainActivity"', 'android:name=".MainActivity"\n            android:showWhenLocked="true"\n            android:turnScreenOn="true"', 1)
manifest.write_text(m)

# ── App build file ──
kts = (app / "build.gradle.kts").exists()
bf = app / ("build.gradle.kts" if kts else "build.gradle")
g = bf.read_text()
g = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 24", g)
g = re.sub(r"minSdkVersion\s+flutter\.minSdkVersion", "minSdkVersion 24", g)
g = g.replace("JavaVersion.VERSION_1_8", "JavaVersion.VERSION_17")
g = re.sub(r"ndkVersion\s*=\s*flutter\.ndkVersion", 'ndkVersion = "27.0.12077973"', g)
if kts:
    g = re.sub(r"compileOptions\s*\{", "compileOptions {\n        isCoreLibraryDesugaringEnabled = true", g, count=1)
    g = g.replace('signingConfig = signingConfigs.getByName("debug")',
                  'signingConfig = signingConfigs.getByName("debug")\n            isMinifyEnabled = false\n            isShrinkResources = false')
    g += '\ndependencies {\n    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")\n}\n'
else:
    g = re.sub(r"compileOptions\s*\{", "compileOptions {\n        coreLibraryDesugaringEnabled true", g, count=1)
    g = g.replace("signingConfig = signingConfigs.debug",
                  "signingConfig = signingConfigs.debug\n            minifyEnabled false\n            shrinkResources false")
    g += "\ndependencies {\n    coreLibraryDesugaring 'com.android.tools:desugar_jdk_libs:2.1.4'\n}\n"
bf.write_text(g)

# ── Toolchain versions (AGP 8.7 / Kotlin 2.1 / Gradle 8.12) ──
for name in ("settings.gradle", "settings.gradle.kts"):
    p = android / name
    if p.exists():
        s = p.read_text()
        s = re.sub(r'(id\s*\(?\s*"com\.android\.application"\s*\)?\s*version\s*)"[^"]+"', r'\g<1>"8.7.3"', s)
        s = re.sub(r'(id\s*\(?\s*"org\.jetbrains\.kotlin\.android"\s*\)?\s*version\s*)"[^"]+"', r'\g<1>"2.1.0"', s)
        p.write_text(s)
wp = android / "gradle/wrapper/gradle-wrapper.properties"
w = wp.read_text()
w = re.sub(r"gradle-[\d.]+-(all|bin)\.zip", "gradle-8.12-all.zip", w)
wp.write_text(w)

# ── Notification channel tones ──
raw = app / "src/main/res/raw"
raw.mkdir(parents=True, exist_ok=True)
for f in (root / "assets/sounds").glob("*.wav"):
    shutil.copy(f, raw / f.name)
(raw / "keep.xml").write_text('<?xml version="1.0" encoding="utf-8"?>\n<resources xmlns:tools="http://schemas.android.com/tools" tools:keep="@raw/*" />\n')

print("patched:", bf.name, "| manifest permissions:", len(perms))
